// 지난 세션 복원: Claude Code의 대화 기록(JSONL)에서 턴과 그 턴의 변경을 되살리는 순수 함수.
// 파일 읽기와 git 실행은 register.js가 한다.
//
// 턴 = 사용자 요청 하나부터 다음 요청 직전까지. 그 턴에서
// - Edit/Write는 기록에 남은 고치기 전 파일(originalFile)과 바꾼 내용으로 정확히 복원하고
// - Bash로 다룬 저장소는 경로만 모아 둔다 (register.js가 그 턴 시간 범위의 커밋을 git에서 찾는다)

// 대화 기록 줄에서 사용자의 요청(시스템이 넣은 <…> 글과 도구 결과는 제외).
// 이미지를 붙인 요청은 내용이 블록 목록이다: 그 안의 글 블록을 쓴다
export function promptText(o) {
  const c = o && o.message && o.message.content
  if (!o || o.type !== 'user' || o.isSidechain) return null
  let t = ''
  if (typeof c === 'string') t = c
  else if (Array.isArray(c) && !c.some((b) => b && b.type === 'tool_result')) t = c.filter((b) => b && b.type === 'text' && b.text).map((b) => b.text).join('\n')
  t = t.trim()
  if (!t || t.startsWith('<') || t.startsWith('[Request interrupted')) return null
  // 붙인 이미지 표시([Image #1], [Image: source: …])는 요청의 내용이 아니다
  const clean = t.replace(/\[Image(?: #\d+|: source: [^\]]*)\]/g, ' ').replace(/[ \t]+/g, ' ').trim()
  return clean || '(이미지)'
}

// 시각(ms) → 이 컴퓨터 시간대의 "MM-DD HH:mm"
export function localDay(ms) {
  if (!ms) return ''
  const d = new Date(ms)
  const p = (n) => String(n).padStart(2, '0')
  return p(d.getMonth() + 1) + '-' + p(d.getDate()) + ' ' + p(d.getHours()) + ':' + p(d.getMinutes())
}

// Claude 자체 데이터와 임시 작업 폴더는 작업 결과가 아니다
export function isWorkPath(path, home) {
  return !path.startsWith(home + '/.claude/') && !/^\/(private\/)?tmp\/claude-/.test(path)
}

function assistantText(o) {
  const c = o.message && o.message.content
  if (o.type !== 'assistant' || !Array.isArray(c)) return ''
  return c.filter((b) => b.type === 'text' && b.text).map((b) => b.text).join('\n').trim()
}

// 편집 하나를 고치기 전 내용에 적용한 결과. 적용할 수 없으면 null
export function applyEdit(original, edit) {
  if (edit.tool === 'Write') return edit.content
  if (original === null || original === undefined) return null
  const steps = edit.tool === 'MultiEdit' ? edit.edits : [{ old_string: edit.old_string, new_string: edit.new_string, replace_all: edit.replace_all }]
  let text = original
  for (const s of steps || []) {
    if (typeof s.old_string !== 'string' || typeof s.new_string !== 'string') return null
    if (!text.includes(s.old_string)) return null
    text = s.replace_all ? text.split(s.old_string).join(s.new_string) : text.replace(s.old_string, s.new_string)
  }
  return text
}

// 대화 기록 줄들 → 턴 목록
// [{ id, startAt, endAt, request, answer, excerpt, files: { 경로: { before, after, tools, agents, skipped } }, bashCommands }]
// agentLines: 서브에이전트 기록 줄들 (시각으로 메인 턴에 붙인다)
export function turnsFromTranscript(lines, agentLines = []) {
  const turns = []
  let cur = null
  const uses = {}
  const events = []

  const parse = (line, agent) => {
    try {
      const o = JSON.parse(line)
      if (agent) o.__agent = agent
      return o
    } catch {
      return null
    }
  }
  const main = lines.map((l) => parse(l, null)).filter(Boolean)
  const subs = agentLines.map((x) => parse(x.line, x.agent)).filter(Boolean)

  for (const o of main) {
    const prompt = promptText(o)
    if (prompt) {
      cur = { id: o.uuid || 't' + turns.length, startAt: o.timestamp || '', endAt: o.timestamp || '', request: prompt, texts: [], files: {}, bashCommands: [], order: [] }
      turns.push(cur)
      continue
    }
    if (!cur) continue
    if (o.timestamp) cur.endAt = o.timestamp
    const text = assistantText(o)
    if (text && !o.isSidechain) cur.texts.push({ at: o.timestamp || '', text })
    events.push({ o, turn: cur })
  }
  // 서브에이전트의 기록은 시각이 들어가는 메인 턴에 붙인다
  for (const o of subs) {
    const at = o.timestamp || ''
    const turn = turns.filter((t) => t.startAt <= at).pop()
    if (turn) events.push({ o, turn })
  }

  for (const { o, turn } of events) {
    const c = o.message && o.message.content
    if (!Array.isArray(c)) continue
    for (const b of c) {
      if (b.type === 'tool_use') {
        if (['Edit', 'Write', 'MultiEdit'].includes(b.name)) uses[b.id] = { tool: b.name, input: b.input || {}, turn, agent: o.__agent }
        else if (b.name === 'Bash' && b.input && typeof b.input.command === 'string') turn.bashCommands.push(b.input.command)
      }
      if (b.type === 'tool_result' && uses[b.tool_use_id]) {
        const u = uses[b.tool_use_id]
        delete uses[b.tool_use_id]
        if (b.is_error) continue
        const r = o.toolUseResult && typeof o.toolUseResult === 'object' ? o.toolUseResult : {}
        const path = r.filePath || u.input.file_path
        if (!path) continue
        const original = typeof r.originalFile === 'string' ? r.originalFile : r.type === 'create' ? null : undefined
        const edit = { tool: u.tool, ...u.input }
        const after = original === undefined ? null : applyEdit(original, edit)
        const f = u.turn.files[path]
        if (!f) {
          u.turn.files[path] = {
            before: original === undefined ? null : original,
            after,
            tools: [u.tool],
            agents: u.agent ? [u.agent] : [],
            // 고치기 전 내용이 기록에 없거나 적용이 안 되면 내용 비교를 하지 않는다
            skipped: original === undefined || after === null ? 'unreadable' : null,
          }
        } else {
          f.after = after
          if (after === null) f.skipped = 'unreadable'
          if (!f.tools.includes(u.tool)) f.tools.push(u.tool)
          if (u.agent && !f.agents.includes(u.agent)) f.agents.push(u.agent)
        }
      }
    }
  }

  return turns.map((t, i) => ({
    id: t.id,
    startAt: t.startAt,
    // 다음 요청 직전까지가 이 턴 (커밋 시간 범위)
    endAt: turns[i + 1] ? turns[i + 1].startAt : t.endAt,
    request: t.request,
    answer: t.texts.length ? t.texts[t.texts.length - 1].text : '',
    // "가자"처럼 짧은 요청은 앞 턴들에 진짜 이유가 있다: 같은 세션의 앞선 요청 몇 개를 함께
    excerpt: priorRequests(turns, i) + turnExcerpt(t),
    files: t.files,
    bashCommands: t.bashCommands,
  }))
}

const PRIOR_TURNS = 4

function priorRequests(turns, i) {
  const prior = turns.slice(Math.max(0, i - PRIOR_TURNS), i)
  if (!prior.length) return ''
  return '## 같은 세션의 앞선 요청 (오래된 것부터)\n' + prior.map((p) => '- ' + (p.request.length > 400 ? p.request.slice(0, 400) + '…' : p.request).replace(/\n+/g, ' ')).join('\n') + '\n\n## 이 턴\n'
}

// 이 턴의 대화: 요청과 Claude의 설명 (해설 프롬프트의 맥락)
function turnExcerpt(t, maxChars = 12000) {
  const parts = ['사용자: ' + t.request, ...t.texts.map((x) => 'Claude: ' + (x.text.length > 2000 ? x.text.slice(0, 2000) + '…' : x.text))]
  let out = parts.join('\n\n')
  if (out.length > maxChars) out = out.slice(0, 2000) + '\n\n…(중간 생략)…\n\n' + out.slice(out.length - (maxChars - 2100))
  return out
}

// 그 턴이 이 커밋을 만들었나. 같은 시간대에 다른 세션도 커밋할 수 있어서 시간만으로는 모른다:
// - 그 턴에 커밋을 만드는 명령(git commit, cherry-pick, merge, revert, am)이 있어야 하고
// - git commit에 메시지를 적어 넣었다면(-m, heredoc) 그 메시지가 커밋 제목과 맞아야 한다
const COMMIT_CMD = /\bgit(?:\s+-[Cc]\s+\S+)*\s+(?:commit|cherry-pick|merge|revert|am)(?![\w-])/
export function madeByTurn(subject, bashCommands) {
  const makers = bashCommands.filter((c) => COMMIT_CMD.test(c))
  if (!makers.length) return false
  const norm = (x) => x.replace(/\s+/g, ' ')
  const head = norm(subject).slice(0, 30)
  const inline = makers.filter((c) => /\bcommit\b[\s\S]*(\s-[a-zA-Z]*m\b|\s--message\b|<<)/.test(c))
  if (inline.length === makers.length) return inline.some((c) => norm(c).includes(head))
  return true
}

// `git log --format=%H%x09%cI%x09%s` → [{ sha, at, subject }]
export function parseLog(text) {
  return text.split('\n').filter(Boolean).map((line) => {
    const [sha, at, ...rest] = line.split('\t')
    return { sha, at, subject: rest.join('\t') }
  })
}

files.hooks/diff.js:
// 줄 단위 diff (Myers 알고리즘). mods API를 쓰지 않는 순수 함수만 둔다.

// 글을 줄 배열로 나눈다. 끝의 줄바꿈 하나는 빈 줄로 세지 않는다
export function splitLines(text) {
  if (text === null || text === undefined || text === '') return []
  const lines = text.split(/\r?\n/)
  if (lines[lines.length - 1] === '') lines.pop()
  return lines
}

// a에서 b로 가는 최단 편집: [{ op: 'eq' | 'del' | 'add', a?: a의 줄 위치, b?: b의 줄 위치 }]
// 위치는 0부터. eq는 a와 b 둘 다, del은 a만, add는 b만 가진다
export function diffLines(a, b) {
  const n = a.length
  const m = b.length
  const max = n + m
  const offset = max
  const v = new Array(2 * max + 2).fill(0)
  const trace = []

  outer: for (let d = 0; d <= max; d++) {
    trace.push(v.slice())
    for (let k = -d; k <= d; k += 2) {
      let x
      if (k === -d || (k !== d && v[offset + k - 1] < v[offset + k + 1])) x = v[offset + k + 1]
      else x = v[offset + k - 1] + 1
      let y = x - k
      while (x < n && y < m && a[x] === b[y]) { x++; y++ }
      v[offset + k] = x
      if (x >= n && y >= m) break outer
    }
  }

  // 지나온 길을 거꾸로 따라가며 편집 목록을 만든다
  const ops = []
  let x = n
  let y = m
  for (let d = trace.length - 1; d >= 0; d--) {
    const vv = trace[d]
    const k = x - y
    let prevK
    if (k === -d || (k !== d && vv[offset + k - 1] < vv[offset + k + 1])) prevK = k + 1
    else prevK = k - 1
    const prevX = vv[offset + prevK]
    const prevY = prevX - prevK
    while (x > prevX && y > prevY) { x--; y--; ops.push({ op: 'eq', a: x, b: y }) }
    if (d > 0) {
      if (x === prevX) { y--; ops.push({ op: 'add', b: y }) }
      else { x--; ops.push({ op: 'del', a: x }) }
    }
  }
  return ops.reverse()
}

// 추가·삭제 줄 수
export function countChanges(ops) {
  let added = 0
  let removed = 0
  for (const o of ops) {
    if (o.op === 'add') added++
    else if (o.op === 'del') removed++
  }
  return { added, removed }
}

// 두 글의 추가·삭제 줄 수 (before가 null이면 새 파일)
export function lineStats(before, after) {
  return countChanges(diffLines(splitLines(before), splitLines(after)))
}

// ── 화면용 diff 행 ───────────────────────────────────────────
// 변경 블록(연속된 추가·삭제) 단위로 묶고, 변경 없는 긴 구간은 접는다.
//
// 행 하나: { kind, left, right, hunk }
//   kind   'eq' 같음 · 'add' 추가만 · 'del' 삭제만 · 'mod' 같은 블록 안에 삭제와 추가가 함께
//   left   { num, text, hi } 또는 null (변경 전 줄, num은 1부터)
//   right  { num, text, hi } 또는 null (변경 후 줄)
//   hi     줄 안에서 바뀐 구간 [[시작, 끝)] (mod 짝 줄에만)
//   hunk   변경 블록 번호 (1부터, eq는 0)
// 접힌 구간: { kind: 'fold', count }

export const CONTEXT = 3

// 이보다 긴 줄은 단어 diff 대신 앞뒤가 같은 부분만 빼고 강조한다 (계산량 제한)
const WORD_DIFF_MAX = 2000

// 줄을 단어·공백·기호 단위로 쪼갠다
function tokens(text) {
  return text.match(/[\p{L}\p{N}_]+|\s+|[^\p{L}\p{N}_\s]/gu) || []
}

// 두 줄에서 바뀐 구간들을 찾는다: { left: [[시작, 끝)], right: [[시작, 끝)] }
// 단어 단위로 diff해서, 바뀐 단어가 이어지는 곳을 한 구간으로 묶는다
export function changedSpan(a, b) {
  if (a.length + b.length > WORD_DIFF_MAX) return edgeSpan(a, b)
  const ta = tokens(a)
  const tb = tokens(b)
  const left = []
  const right = []
  let pa = 0
  let pb = 0
  const push = (list, s, e) => {
    const last = list[list.length - 1]
    if (last && last[1] === s) last[1] = e
    else list.push([s, e])
  }
  for (const o of diffLines(ta, tb)) {
    if (o.op === 'eq') { pa += ta[o.a].length; pb += tb[o.b].length; continue }
    if (o.op === 'del') { push(left, pa, pa + ta[o.a].length); pa += ta[o.a].length }
    else { push(right, pb, pb + tb[o.b].length); pb += tb[o.b].length }
  }
  return { left, right }
}

// 앞뒤의 같은 부분을 뺀 가운데 한 구간
function edgeSpan(a, b) {
  let start = 0
  while (start < a.length && start < b.length && a[start] === b[start]) start++
  let endA = a.length
  let endB = b.length
  while (endA > start && endB > start && a[endA - 1] === b[endB - 1]) { endA--; endB-- }
  return { left: endA > start ? [[start, endA]] : [], right: endB > start ? [[start, endB]] : [] }
}

export function buildRows(beforeText, afterText, context = CONTEXT) {
  const a = splitLines(beforeText)
  const b = splitLines(afterText)
  const ops = diffLines(a, b)
  const rows = []
  let hunk = 0
  let i = 0
  while (i < ops.length) {
    if (ops[i].op === 'eq') {
      const o = ops[i]
      rows.push({ kind: 'eq', left: { num: o.a + 1, text: a[o.a] }, right: { num: o.b + 1, text: b[o.b] }, hunk: 0 })
      i++
      continue
    }
    // 연속된 추가·삭제를 한 블록으로
    const dels = []
    const adds = []
    while (i < ops.length && ops[i].op !== 'eq') {
      if (ops[i].op === 'del') dels.push(ops[i].a)
      else adds.push(ops[i].b)
      i++
    }
    hunk++
    const kind = dels.length && adds.length ? 'mod' : dels.length ? 'del' : 'add'
    const n = Math.max(dels.length, adds.length)
    for (let k = 0; k < n; k++) {
      const l = k < dels.length ? { num: dels[k] + 1, text: a[dels[k]], hi: [] } : null
      const r = k < adds.length ? { num: adds[k] + 1, text: b[adds[k]], hi: [] } : null
      if (l && r) {
        const span = changedSpan(l.text, r.text)
        l.hi = span.left
        r.hi = span.right
      }
      rows.push({ kind, left: l, right: r, hunk })
    }
  }
  return { rows: fold(rows, context), hunks: hunk }
}

// 변경 블록에서 context줄보다 먼 같은 줄은 접는다. 숨길 줄이 한 줄뿐이면 접지 않고 보여 준다
function fold(rows, context) {
  const near = rows.map(() => false)
  rows.forEach((r, i) => {
    if (r.kind === 'eq') return
    for (let k = Math.max(0, i - context); k <= Math.min(rows.length - 1, i + context); k++) near[k] = true
  })
  const out = []
  let hidden = []
  const flush = () => {
    if (hidden.length === 1) out.push(hidden[0])
    else if (hidden.length > 1) out.push({ kind: 'fold', count: hidden.length })
    hidden = []
  }
  rows.forEach((r, i) => {
    if (r.kind === 'eq' && !near[i]) { hidden.push(r); return }
    flush()
    out.push(r)
  })
  flush()
  return out
}

files.hooks/generate.js:
// 해설 생성: 모델에 보낼 프롬프트와, 돌아온 JSON의 검증. mods API를 쓰지 않는 순수 함수만 둔다.
//
// 원칙 (SPEC 5장, teach·wait-what 스킬)
// - 모델은 구조(JSON)만 돌려준다. 그리기는 mod가 한다
// - 코드 조각은 모델이 쓰지 않는다. 위치(path:줄)만 받고 mod가 스냅숏에서 읽는다
// - 대화 기록에 근거가 없는 "왜"는 (추정)으로 표시하게 한다
// - 이미 아는 용어(Known)는 짧게, 정의하지 않은 용어는 쓰지 않게 한다

export const SECTIONS = [
