// 화면 공통 도우미. `el`은 $.ui.resolve(e)가 준 요소 생성자 묶음.
//
// 그리기 규칙 (SPEC 4.6)
// - 한 줄에 여러 색이 필요하면 Text 하나 안에 Text를 넣는다. 조각을 Box 가로줄로
//   늘어놓으면 좁은 창에서 조각마다 따로 줄바꿈되어 글자가 뒤섞인다.
// - 다이어그램과 코드 줄은 줄바꿈 대신 잘라낸다(wrap: 'truncate-end').
// - 한글은 2칸을 차지하므로 다이어그램 줄에서 한글은 줄 끝에만 둔다.

const DARK = {
  C: {
    fg: '#d6d6d6', title: '#f0f0f0', dim: '#858b94', faint: '#5c6370', rule: '#2f3238',
    accent: '#e3a857', blue: '#79b8ff', green: '#7fc79a', red: '#f08c7c', purple: '#c3a6ff',
  },
  // diff 배경색 (인텔리제이 다크 테마 계열)
  D: {
    add: '#1f3a28', addHi: '#2f6e41', mod: '#1c2c43', modHi: '#2f5a8f', modFill: '#151d29',
    del: '#2a2c31', fill: '#16171a', rem: '#3a2326', remHi: '#6e2f36',
  },
}

const LIGHT = {
  C: {
    fg: '#1f2328', title: '#0d1117', dim: '#57606a', faint: '#8c959f', rule: '#d0d7de',
    accent: '#9a6700', blue: '#0969da', green: '#1a7f37', red: '#cf222e', purple: '#8250df',
  },
  D: {
    add: '#dafbe1', addHi: '#aceebb', mod: '#ddf4ff', modHi: '#b6e3ff', modFill: '#f1f8ff',
    del: '#eaeef2', fill: '#f6f8fa', rem: '#ffebe9', remHi: '#ffcecb',
  },
}

// 화면이 쓰는 색. applyTheme으로 바꾼다
export const C = { ...DARK.C }
export const D = { ...DARK.D }

// 설정 theme: 'dark'(기본) 또는 'light'
export function applyTheme(name) {
  const t = name === 'light' ? LIGHT : DARK
  Object.assign(C, t.C)
  Object.assign(D, t.D)
}

// 한 줄(또는 한 문단) 안의 색 조각들: parts = ['plain' | [text, color, bold?, background?], ...]
export function rich(el, parts, opts) {
  return el.Text({
    color: C.fg,
    ...(opts || {}),
    children: parts.map((p) => {
      if (typeof p === 'string') return p
      const props = { color: p[1], bold: !!p[2], children: [p[0]] }
      if (p[3]) props.backgroundColor = p[3]
      return el.Text(props)
    }),
  })
}

export function rule(el, cols) {
  return el.Text({ color: C.rule, wrap: 'truncate-end', children: ['─'.repeat(Math.max(10, cols))] })
}

// 버튼: Claude Code 기본 버튼. 터미널에서는 [ d diff ], Desktop 앱에서는 네이티브 버튼.
// 대괄호 버튼은 단축키를 따로 표시하지 않으므로 라벨 앞에 키를 넣는다. primary는 화면마다 하나
export function btn(el, { key, hotkey, label, onPress, primary, dim }) {
  const props = { key, label: hotkey ? hotkey + ' ' + label : label, onPress }
  if (hotkey) props.hotkey = hotkey
  if (primary) props.variant = 'primary'
  if (dim) props.dimColor = true
  return el.Button(props)
}

// 대괄호 없는 글자 링크: 목차·파일 탭처럼 여러 개를 늘어놓을 때
export function link(el, { key, label, onPress, dim }) {
  const props = { key, label, plain: true, onPress }
  if (dim) props.dimColor = true
  return el.Button(props)
}

// 가운뎃점으로 구분한 링크 줄
export function linkRow(el, links) {
  return el.Box({
    flexDirection: 'row',
    flexWrap: 'wrap',
    children: links.flatMap((l, i) => [...(i ? [el.Text({ color: C.faint, children: ['  ·  '] })] : []), l]),
  })
}

export function buttonRow(el, children) {
  return el.Box({ flexDirection: 'row', flexWrap: 'wrap', columnGap: 1, children })
}

// 색 조각들의 앞에서 n글자를 버린다 (가로 스크롤)
export function shift(parts, n) {
  const out = []
  let rest = n
  for (const p of parts) {
    const t = p[0]
    if (rest >= t.length) { rest -= t.length; continue }
    out.push(rest ? [t.slice(rest), p[1], p[2], p[3]] : p)
    rest = 0
  }
  return out
}

files.hooks/views/diff.js:
// diff 창 (인텔리제이식). 위쪽 안내·버튼과 아래쪽 위치 설명은 고정하고,
// 가운데 코드 영역만 위아래(top)·좌우(left)로 민다.
//
// files: [{ path, isNew, skipped, added, removed, agents, rows, hunks }]  (rows는 diff.js의 buildRows)

import { C, D, btn, buttonRow, linkRow, link, rich, rule, shift } from './common.js'

// 창이 이 너비 이상이면 좌우 비교, 좁으면 통합 보기
export const SIDE_BY_SIDE_COLS = 96

// 모든 파일의 변경 블록을 순서대로: [{ f: 파일 위치, h: 블록 번호 }]
export function hunkList(files) {
  const out = []
  files.forEach((file, f) => {
    for (let h = 1; h <= (file.hunks || 0); h++) out.push({ f, h })
  })
  return out
}

// 바뀐 구간 [[시작, 끝)]으로 한 줄을 색 조각으로 나눈다
function segments(text, ranges, hi, fg) {
  if (!text) return [[' ', fg]]
  if (!hi || !ranges || !ranges.length) return [[text, fg]]
  const out = []
  let at = 0
  for (const [s, e] of ranges) {
    if (s > at) out.push([text.slice(at, s), fg])
    out.push([text.slice(s, e), fg, false, hi])
    at = e
  }
  if (at < text.length) out.push([text.slice(at), fg])
  return out
}

function filled(el, width, bg, child) {
  const props = { width, flexShrink: 0, children: [child] }
  if (bg) props.backgroundColor = bg
  return el.Box(props)
}

const sideBg = (row, side) => {
  const has = row[side] !== null
  if (row.kind === 'eq') return null
  if (row.kind === 'add') return side === 'left' ? D.fill : D.add
  if (row.kind === 'del') return side === 'left' ? D.del : D.fill
  return has ? D.mod : D.modFill
}

// 보고 있는 파일을 화면 줄 목록으로 만든다 (그리기 전 데이터)
export function diffModel(cols, files, pos) {
  const hunks = hunkList(files)
  const cur = hunks[pos] || { f: 0, h: 0 }
  const file = files[cur.f]
  const side = cols >= SIDE_BY_SIDE_COLS
  const lines = []
  let hunkStart = -1
  let longest = 0
  const mark = (row) => (row.hunk && row.hunk === cur.h ? '>' : ' ')
  const startHere = (row) => { if (hunkStart < 0 && row.hunk === cur.h) hunkStart = lines.length }

  const rows = (file && file.rows) || []
  for (let i = 0; i < rows.length; i++) {
    const row = rows[i]
    if (row.kind === 'fold') { lines.push({ fold: row.count }); continue }
    longest = Math.max(longest, ((row.left && row.left.text) || '').length + 2, ((row.right && row.right.text) || '').length + 2)
    if (side) {
      startHere(row)
      const hiL = row.kind === 'mod' ? D.modHi : null
      const hiR = row.kind === 'mod' ? D.modHi : null
      lines.push({
        mark: mark(row),
        l: { num: row.left ? row.left.num : '', parts: segments(row.left && row.left.text, row.left && row.left.hi, hiL, row.kind === 'del' ? C.dim : C.fg), bg: sideBg(row, 'left') },
        r: { num: row.right ? row.right.num : '', parts: segments(row.right && row.right.text, row.right && row.right.hi, hiR, C.fg), bg: sideBg(row, 'right') },
      })
      continue
    }
    // 통합 보기: 한 블록의 지운 줄(−)을 모두 보여 준 뒤 추가한 줄(+)
    if (row.kind === 'eq') {
      lines.push({ mark: ' ', num: row.right.num, parts: [['  ' + row.right.text, C.dim]], bg: null })
      continue
    }
    const block = []
    while (i < rows.length && rows[i].hunk === row.hunk && rows[i].kind !== 'fold') block.push(rows[i++])
    i--
    startHere(row)
    for (const r of block) {
      if (r.left) lines.push({ mark: mark(r), num: r.left.num, parts: [['− ', C.red], ...segments(r.left.text, r.left.hi, D.remHi, C.fg)], bg: D.rem })
    }
    for (const r of block) {
      if (r.right) lines.push({ mark: mark(r), num: r.right.num, parts: [['+ ', C.green], ...segments(r.right.text, r.right.hi, D.addHi, C.fg)], bg: D.add })
    }
  }
  const codeCols = side ? Math.floor((cols - 1) / 2) - 6 : cols - 6
  return { hunks, cur, file, side, lines, hunkStart: Math.max(0, hunkStart), maxLeft: Math.max(0, longest - codeCols) }
}

// 코드 영역에 보일 줄 수: 창 높이에서 고정된 위아래 영역을 뺀 만큼
export function diffCodeRows(bodyRows) {
  return Math.max(6, bodyRows - 13)
}

// 변경 블록의 줄 범위를 "14–17줄"처럼
function hunkRange(file, h) {
  const nums = (file.rows || []).filter((r) => r.hunk === h).map((r) => (r.right || r.left).num)
  if (!nums.length) return ''
  const a = Math.min(...nums)
  const b = Math.max(...nums)
  return a === b ? a + '줄' : a + '–' + b + '줄'
}

// st = { turn, files, pos, top, left }. on = { prev, next, nextFile, pickFile, up, down, leftward, rightward, back? }
export function diffView(el, cols, bodyRows, st, on) {
  const m = diffModel(cols, st.files, st.pos)
  const codeRows = diffCodeRows(bodyRows)
  const top = Math.min(st.top, Math.max(0, m.lines.length - codeRows))
  const left = Math.min(st.left, m.maxLeft)
  const half = Math.floor((cols - 1) / 2)
  const file = m.file

  const header = rich(el, [
    ['diff  ', C.accent, true],
    ['#' + st.turn.seq + '  ', C.accent],
    [st.turn.title, C.title, true],
    ['   파일 ' + st.files.length + '개  ', C.dim],
    ['+' + st.turn.added, C.green], ' ', ['−' + st.turn.removed, C.red],
  ], { wrap: 'truncate-end' })

  // 파일 탭: 대괄호 없는 링크. 보고 있는 파일은 밝게
  const tabs = linkRow(el, st.files.map((f, i) =>
    link(el, { key: 'tab-' + i, label: f.path.split('/').pop(), dim: i !== m.cur.f, onPress: () => on.pickFile(i) }),
  ))

  const nav = buttonRow(el, [
    btn(el, { key: 'prev', hotkey: 'p', label: '이전 변경', dim: st.pos === 0, onPress: on.prev }),
    btn(el, { key: 'next', hotkey: 'n', label: '다음 변경', primary: true, dim: st.pos >= m.hunks.length - 1, onPress: on.next }),
    btn(el, { key: 'next-file', hotkey: 'f', label: '다음 파일', dim: st.files.length < 2, onPress: on.nextFile }),
    ...(on.back ? [btn(el, { key: 'back', hotkey: 'b', label: '해설로', onPress: on.back })] : []),
    el.Text({ color: C.accent, children: [m.hunks.length ? ' 변경 ' + (st.pos + 1) + '/' + m.hunks.length : ' 변경 없음'] }),
  ])

  const scroll = buttonRow(el, [
    btn(el, { key: 'up', hotkey: 'k', label: '위', dim: top === 0, onPress: on.up }),
    btn(el, { key: 'down', hotkey: 'j', label: '아래', dim: top + codeRows >= m.lines.length, onPress: on.down }),
    btn(el, { key: 'left', hotkey: 'h', label: '왼쪽', dim: left === 0, onPress: on.leftward }),
    btn(el, { key: 'right', hotkey: 'l', label: '오른쪽', dim: left >= m.maxLeft, onPress: on.rightward }),
    el.Text({
      color: C.faint,
      children: [' 줄 ' + (m.lines.length ? top + 1 : 0) + '–' + Math.min(top + codeRows, m.lines.length) + ' / ' + m.lines.length + (left ? '  ·  가로 +' + left : '') + '  ·  휠로도 스크롤'],
    }),
  ])

  const agents = file && file.agents && file.agents.length ? '  서브에이전트 · ' + file.agents.map((a) => a.type || a.agentId).join(', ') : ''
  const meta = !file ? el.Text({ color: C.dim, children: ['바뀐 파일이 없습니다.'] }) : rich(el, [
    [file.path, C.blue],
    '  ',
    file.skipped ? ['내용 생략', C.dim] : file.isNew ? ['새 파일', C.green] : ['수정', C.blue],
    '  ',
    ['+' + file.added, C.green], ' ', ['−' + file.removed, C.red],
    agents ? [agents, C.purple] : '',
    ['  ·  ' + (m.side ? '좌우 보기' : '통합 보기 (창이 좁음)'), C.faint],
  ], { wrap: 'truncate-end' })

  const code = []
  if (file && file.skipped) {
    const why = { 'too-large': '4MB가 넘는 파일', binary: '바이너리 파일', unreadable: '읽을 수 없는 파일' }[file.skipped] || file.skipped
    code.push(el.Text({ color: C.dim, children: ['  ' + why + '이라 내용을 비교하지 않았습니다.'] }))
  } else {
    if (m.side) {
      code.push(el.Box({
        flexDirection: 'row',
        children: [
          filled(el, half, null, el.Text({ color: C.faint, children: ['      변경 전 · 턴 시작 시점'] })),
          el.Text({ color: C.rule, children: ['│'] }),
          filled(el, half, null, el.Text({ color: C.faint, children: ['      변경 후 · 턴 종료 시점'] })),
        ],
      }))
    }
    // 코드 줄은 끌거나 ←/→ 로 가로 이동하는 창(pan.js)에 담는다. 위아래는 여기서 잘라 넘긴다
    const fixed = (mark, num) => [[mark, C.accent, true], [String(num).padStart(4, ' ') + ' ', C.faint]]
    const rows = m.lines.slice(top, top + codeRows).map((ln) => {
      if (ln.fold) return { center: ['··· 변경 없는 ' + ln.fold + '줄 ···', C.faint] }
      if (m.side) {
        return {
          segs: [
            { fixed: fixed(ln.mark, ln.l.num), parts: ln.l.parts, bg: ln.l.bg },
            { fixed: fixed(ln.mark, ln.r.num), parts: ln.r.parts, bg: ln.r.bg },
          ],
          sep: C.rule,
        }
      }
      return { segs: [{ fixed: fixed(ln.mark, ln.num), parts: ln.parts, bg: ln.bg }] }
    })
    code.push(el.Client({ key: 'pan-diff', module: './pan.js', width: cols, props: { id: 'diff', left: st.left, rows } }))
  }

  // 아래쪽: 지금 보고 있는 변경의 위치. 변경별 한 줄 해설은 해설 생성 단계에서 붙는다
  const where = file && m.hunks.length && !file.skipped
    ? rich(el, [['변경 ' + (st.pos + 1) + '  ', C.accent, true], [file.path + '  ' + hunkRange(file, m.cur.h), C.fg], st.notes && st.notes[st.pos] ? ['  ' + st.notes[st.pos], C.dim] : ''])
    : el.Text({ children: [' '] })

  return el.Box({
    flexDirection: 'column',
    children: [header, tabs, nav, scroll, rule(el, cols), meta, ...code, rule(el, cols), where],
  })
}

files.hooks/views/explain.js:
// 해설 창. 섹션 데이터는 모델이 만든 JSON(generate.js의 검증을 거친 것)이다.
//
// st = {
//   turn, files,                      턴 기록과 화면용 파일
//   sections: { id: { status, data, error } }   status: none | loading | done | error
//   open: { id: bool }, current,      펼친 섹션, r(다시 만들기)의 대상
//   threads: { id: [{ type: 'easy', text } | { type: 'q', q, a }] }   Wait, what? 대화 (null이면 만드는 중)
//   qa: [{ q, a }], known: [용어], quiz: { order, picked }, understood, seqLeft, pans: { 'walk-1': 가로 위치 },
//   codeFor: (at) => { title, lines: [{ num, text }] } | null    코드 위치를 스냅숏에서 읽은 결과
// }

import { SECTIONS } from '../generate.js'
import { C, btn, buttonRow, link, linkRow, rich, rule } from './common.js'
import { flowView, seqMaxLeft, seqView } from './diagrams.js'
import { usageText } from './list.js'

// 이 회차부터는 더 설명하기보다 어디가 막히는지 묻는다
export const EASY_ASK_AFTER = 3
export const STEP_COLS = 8

function heading(el, text) {
  return el.Text({ bold: true, color: C.accent, children: [text] })
}

function block(el, title, children) {
  return el.Box({ flexDirection: 'column', children: [heading(el, title), el.Box({ flexDirection: 'column', paddingLeft: 2, children })] })
}

function labeled(el, label, color, text) {
  return el.Box({
    flexDirection: 'column',
    children: [el.Text({ bold: true, color, children: [label] }), el.Box({ paddingLeft: 2, children: [el.Text({ children: [text] })] })],
  })
}

// ── 섹션들 ───────────────────────────────────────────────────

function summaryView(el, data, files, onFile) {
  const descOf = (path) => (data.files.find((f) => f.path === path) || {}).desc || ''
  const children = [
    block(el, '무엇을 바꿨나', [
      ...files.map((f, i) =>
        el.Box({
          flexDirection: 'column',
          children: [
            btn(el, { key: 'file-' + i, label: f.path + '  →  diff', onPress: () => onFile(i) }),
            rich(el, [
              '  ',
              f.skipped ? ['내용 생략', C.dim] : f.isNew ? ['새 파일', C.green] : ['수정', C.blue],
              '  ', ['+' + f.added, C.green], f.removed ? ' ' : '', f.removed ? ['−' + f.removed, C.red] : '',
              f.agents.length ? ['  서브에이전트', C.purple] : '',
              descOf(f.path) ? ['  ' + descOf(f.path), C.dim] : '',
            ]),
          ],
        }),
      ),
    ]),
  ]
  if (data.why.length) children.push(block(el, '왜 이렇게 했나', data.why.map((w) => el.Text({ children: [w] }))))
  if (data.how.length) {
    children.push(block(el, '어떻게 동작하나', data.how.flatMap((h, i) => [
      rich(el, [[(i + 1) + ' ', C.accent], [h.label, C.blue]]),
      el.Box({ paddingLeft: 2, children: [el.Text({ color: C.dim, children: [h.detail] })] }),
    ])))
  }
  if (data.review.length) {
    children.push(block(el, '검토할 점', data.review.map((r) =>
      rich(el, [r.kind === 'warn' ? ['! ', C.red, true] : ['? ', C.blue, true], r.text]),
    )))
  }
  return el.Box({ flexDirection: 'column', rowGap: 1, children })
}

function backgroundView(el, data) {
  const children = []
  if (data.problem) children.push(block(el, '무슨 문제가 있었나', [el.Text({ children: [data.problem] })]))
  if (data.cause) {
    children.push(block(el, '왜 그랬나', [
      el.Text({ children: [data.cause] }),
      ...(data.causeAt ? [el.Text({ color: C.blue, children: [data.causeAt] })] : []),
    ]))
  }
  if (data.goal) children.push(block(el, '이번 변경의 목표', [el.Text({ children: [data.goal] })]))
  if (data.outOfScope.length) children.push(block(el, '이번에 다루지 않은 것', data.outOfScope.map((x) => rich(el, [['- ', C.faint], [x, C.dim]]))))
  return el.Box({ flexDirection: 'column', rowGap: 1, children })
}

function walkView(el, data, codeFor, width, pans) {
  return el.Box({
    flexDirection: 'column',
    rowGap: 1,
    children: [
      el.Text({ color: C.dim, children: ['실제 코드를 순서대로 따라가며 각 줄이 하는 일과 그렇게 한 이유를 설명합니다.'] }),
      ...data.steps.map((st, i) => {
        const code = codeFor(st.at)
        return el.Box({
          flexDirection: 'column',
          rowGap: 1,
          children: [
            el.Box({
              flexDirection: 'column',
              children: [
                rich(el, [[(i + 1) + '단계  ', C.accent, true], [st.title, C.title, true]]),
                el.Text({ color: C.blue, wrap: 'truncate-start', children: [st.at || '(위치 없음)'] }),
              ],
            }),
            // 긴 코드 줄은 끌거나 ←/→ 로 가로 이동
            code
              ? el.Box({
                  paddingLeft: 1,
                  children: [el.Client({
                    key: 'pan-walk-' + i,
                    module: './pan.js',
                    width: Math.max(20, width - 1),
                    props: {
                      id: 'walk-' + i,
                      left: (pans && pans['walk-' + i]) || 0,
                      rows: code.lines.map((ln) => ({ segs: [{ fixed: [[String(ln.num).padStart(4, ' ') + ' ┃ ', C.faint]], parts: [[ln.text, code.deleted ? C.dim : C.fg]] }] })),
                      hint: C.faint,
                    },
                  })],
                })
              : el.Text({ color: C.faint, children: ['  (이 위치의 코드를 스냅숏에서 찾지 못했습니다)'] }),
            labeled(el, '하는 일', C.green, st.does),
            ...(st.why ? [labeled(el, '이유', C.accent, st.why)] : []),
            ...(st.alt ? [labeled(el, '검토한 다른 방법', C.purple, st.alt)] : []),
          ],
        })
      }),
    ],
  })
}

function baView(el, data) {
  const tone = { better: C.green, same: C.dim, worse: C.red }
  return el.Box({
    flexDirection: 'column',
    rowGap: 1,
    children: data.rows.map((r) =>
      el.Box({
        flexDirection: 'column',
        children: [
          el.Text({ bold: true, color: C.title, children: [r.when] }),
          rich(el, ['  ', [r.before, C.dim], ['  →  ', C.faint], [r.after, tone[r.tone], true]]),
        ],
      }),
    ),
  })
}

function impactView(el, data) {
  return el.Box({
    flexDirection: 'column',
    rowGap: 1,
    children: data.groups.map((g) =>
      block(el, g.title, g.items.map((it) =>
        el.Box({
          flexDirection: 'column',
          children: [
            el.Text({ color: C.blue, wrap: 'truncate-start', children: [it.path || '-'] }),
            rich(el, ['  ', [it.desc, C.fg], it.flag ? ['  ' + it.flag, C.red, true] : '']),
          ],
        }),
      )),
    ),
  })
}

function termsView(el, data, known, onToggle) {
  if (!data.terms.length) return el.Text({ color: C.dim, children: ['새로 알아야 할 용어가 없습니다.'] })
  const rows = data.terms.map((t) => {
    const isKnown = known.includes(t.term)
    const button = btn(el, { key: 'term-' + t.id, label: isKnown ? 'Undo' : 'Known', onPress: () => onToggle(t.term) })
    if (isKnown) {
      return el.Box({ flexDirection: 'row', flexWrap: 'wrap', columnGap: 2, children: [rich(el, [['✓ ', C.green], [t.term, C.dim]]), button] })
    }
    return el.Box({
      flexDirection: 'column',
      children: [
        el.Box({ flexDirection: 'row', flexWrap: 'wrap', columnGap: 2, children: [rich(el, [[t.term, C.title, true], t.en ? ['  ' + t.en, C.faint] : '']), button] }),
        el.Box({ paddingLeft: 2, children: [el.Text({ children: [t.def] })] }),
      ],
    })
  })
  return el.Box({
    flexDirection: 'column',
    rowGap: 1,
    children: [el.Text({ color: C.dim, children: ['이 변경에 필요한 개념입니다. 이미 아는 것은 [Known]을 누르면 다음 해설부터 짧게 넘어갑니다.'] }), ...rows],
  })
}

// quiz = { order: [[보기 원래 위치...]], picked: [고른 원래 위치 | null] }. 원래 위치 0이 정답
function quizView(el, data, quiz, on) {
  const answered = quiz.picked.filter((x) => x !== null).length
  const correct = quiz.picked.filter((x) => x === 0).length
  const total = data.questions.length
  const done = answered === total
  return el.Box({
    flexDirection: 'column',
    rowGap: 1,
    children: [
      el.Text({ color: C.dim, children: ['기억에서 떠올리며 풀어 보세요. 다 맞히면 이 턴이 이해함으로 표시됩니다.'] }),
      ...data.questions.map((qz, i) => {
        const picked = quiz.picked[i]
        const options = quiz.order[i].map((orig, j) => {
          const label = String.fromCharCode(65 + j) + '  ' + qz.options[orig]
          if (picked === null) return btn(el, { key: 'q' + i + '-o' + orig, label, onPress: () => on.pick(i, orig) })
          const mark = orig === 0 ? '✓ ' : orig === picked ? '✗ ' : '  '
          return el.Text({ color: orig === 0 ? C.green : orig === picked ? C.red : C.faint, children: [mark + label] })
        })
        return el.Box({
          flexDirection: 'column',
          children: [
            rich(el, [['Q' + (i + 1) + '  ', C.accent, true], [qz.q, C.title, true]]),
            el.Box({ flexDirection: 'column', paddingLeft: 2, children: options }),
            picked === null
              ? el.Text({ children: [' '] })
              : el.Box({ paddingLeft: 2, children: [rich(el, [[picked === 0 ? '맞았습니다. ' : '틀렸습니다. ', picked === 0 ? C.green : C.red, true], [qz.explain, C.fg]])] }),
          ],
        })
      }),
      done
        ? el.Box({
            flexDirection: 'row',
            flexWrap: 'wrap',
            columnGap: 2,
            children: [
              rich(el, [[correct + '/' + total + ' 정답', correct === total ? C.green : C.accent, true],
                [correct === total ? '  이 턴을 이해함으로 표시했습니다.' : '  틀린 문제의 이유를 읽고 다시 풀어 보세요.', C.dim]]),
              ...(correct === total ? [] : [btn(el, { key: 'quiz-retry', label: '다시 풀기', onPress: on.quizRetry })]),
            ],
          })
        : el.Text({ color: C.faint, children: [answered + '/' + total + ' 답함'] }),
    ],
  })
}

// ── Wait, what? 대화 상자 ───────────────────────────────────

function threadBox(el, id, thread, on) {
  const busy = thread.some((x) => (x.type === 'easy' ? x.text === null : x.a === null))
  const rounds = thread.filter((x) => x.type === 'easy').length
  const askFirst = rounds >= EASY_ASK_AFTER
  let round = 0
  const ask = { key: 'easy-ask-' + id, label: '이 부분 질문', placeholder: '어디가 막히는지 적고 Enter', value: '', submitLabel: '묻기', onSubmit: (v) => { if (v.trim()) on.askSection(id, v.trim()) } }
  if (askFirst) ask.autoFocus = true
  return el.Box({
    key: 'easy-box-' + id,
    marginLeft: 2,
    marginTop: 1,
    borderStyle: 'round',
    borderColor: C.blue,
    paddingX: 1,
    flexDirection: 'column',
    rowGap: 1,
    children: [
      el.Text({ bold: true, color: C.blue, children: ['Wait, what?  쉬운 말로 다시 설명'] }),
      ...thread.map((x) => {
        if (x.type === 'easy') {
          round += 1
          return el.Box({
            flexDirection: 'column',
            children: [
              el.Text({ bold: true, color: C.blue, children: ['설명 ' + round] }),
              x.text === null ? el.Text({ color: C.dim, children: ['쉬운 말로 다시 설명하는 중…'] }) : el.Text({ children: [x.text] }),
            ],
          })
        }
        return el.Box({
          flexDirection: 'column',
          children: [
            rich(el, [['Q  ', C.accent, true], [x.q, C.title]]),
            x.a === null ? el.Text({ color: C.dim, children: ['   답을 만드는 중…'] }) : rich(el, [['A  ', C.green, true], [x.a, C.fg]]),
          ],
        })
      }),
      ...(askFirst ? [rich(el, [['세 번 설명했는데도 막힌다면 ', C.dim], ['어느 문장, 어느 단어', C.accent, true], ['에서 막히는지 아래에 적어 주세요. 그 지점부터 다시 설명합니다.', C.dim]])] : []),
      buttonRow(el, [btn(el, {
        key: 'easy-again-' + id,
        label: askFirst ? 'Wait, what?  그래도 한 번 더' : 'Wait, what?  아직 모르겠어요',
        primary: !askFirst,
        dim: busy || askFirst,
        onPress: () => { if (!busy) on.easy(id) },
      })]),
      el.Input(ask),
    ],
  })
}

function statusOf(sec) {
  if (sec.status === 'done') return ['● 생성됨', C.green]
  if (sec.status === 'loading') return ['◌ 만드는 중', C.accent]
  if (sec.status === 'error') return ['✗ 만들지 못함 · r로 다시', C.red]
  return ['○ 펼치면 생성', C.faint]
}

// ── 해설 창 전체 ─────────────────────────────────────────────

export function explainView(el, cols, st, on) {
  const t = st.turn
  const summary = st.sections.summary
  const changed = st.files
  const allOpen = SECTIONS.every((s) => st.open[s.id])
  const agents = [...new Set(changed.flatMap((f) => f.agents.map((a) => a.type || 'subagent')))]
  const when = new Date(t.endedAt || t.startedAt)
  const hhmm = String(when.getHours()).padStart(2, '0') + ':' + String(when.getMinutes()).padStart(2, '0')

  const header = el.Box({
    flexDirection: 'column',
    children: [
      rich(el, [['#' + t.seq + '  ', C.accent, true], [t.title, C.title, true]]),
      rich(el, [
        ['파일 ' + changed.length + '개  ', C.dim], ['+' + t.added, C.green], ' ', ['−' + t.removed, C.red],
        agents.length ? ['  ·  서브에이전트 ' + agents.join(', '), C.dim] : '',
        ['  ·  ' + hhmm + '  ·  ', C.dim],
        st.understood ? ['✓ 이해함 (퀴즈 통과)', C.green, true] : ['○ 아직 확인 안 함', C.faint],
      ], { wrap: 'truncate-end' }),
      rich(el, [['해설에 쓴 토큰  ', C.faint], [usageText(st.usage), C.dim]], { wrap: 'truncate-end' }),
      el.Text({ children: [' '] }),
      rich(el, [['요청 ', C.faint], [t.request, C.dim]]),
      el.Box({
        marginTop: 1,
        borderStyle: 'round',
        borderColor: summary.status === 'error' ? C.red : C.accent,
        paddingX: 1,
        flexDirection: 'column',
        children: [
          el.Text({ bold: true, color: C.accent, children: ['한 줄 요약'] }),
          summary.status === 'done'
            ? el.Text({ color: C.title, children: [summary.data.tldr] })
            : summary.status === 'error'
              ? el.Text({ color: C.red, children: ['요약을 만들지 못했습니다: ' + summary.error + '  (r로 다시)'] })
              : el.Text({ color: C.dim, children: ['현재 대화를 바탕으로 요약을 만드는 중…'] }),
        ],
      }),
      el.Box({ marginTop: 1, children: [buttonRow(el, [
        btn(el, { key: 'diff', hotkey: 'd', label: 'diff', primary: true, onPress: () => on.openDiff() }),
        btn(el, { key: 'all', hotkey: 'a', label: allOpen ? '모두 접기' : '모두 펼치기', onPress: () => on.toggleAll(!allOpen) }),
        btn(el, { key: 'regen', hotkey: 'r', label: '다시 만들기', dim: st.sections[st.current].status === 'loading', onPress: on.regen }),
        btn(el, { key: 'go-quiz', hotkey: 'q', label: '퀴즈', onPress: on.goQuiz }),
        ...(on.list ? [btn(el, { key: 'go-list', hotkey: 't', label: '목록', onPress: on.list })] : []),
      ])] }),
      el.Box({
        marginTop: 1,
        children: [linkRow(el, SECTIONS.map((sec) => link(el, {
          key: 'toc-' + sec.id,
          label: sec.key + ' ' + sec.title,
          dim: !st.open[sec.id],
          onPress: () => on.toc(sec.id),
        })))],
      }),
    ],
  })

  const body = []
  SECTIONS.forEach((s) => {
    const sec = st.sections[s.id]
    const [status, statusColor] = statusOf(sec)
    const isOpen = !!st.open[s.id]
    const thread = st.threads[s.id]
    body.push(rule(el, cols))
    body.push(el.Box({
      key: 'sec-' + s.id,
      flexDirection: 'row',
      justifyContent: 'space-between',
      children: [
        btn(el, { key: 'btn-' + s.id, hotkey: s.key, label: s.title + (isOpen ? '  ▾' : '  ▸'), onPress: () => on.toggle(s.id) }),
        el.Box({
          flexDirection: 'row',
          columnGap: 2,
          children: [
            ...(isOpen && sec.status === 'done' && !thread ? [btn(el, { key: 'easy-' + s.id, label: 'Wait, what?', primary: true, onPress: () => on.easy(s.id) })] : []),
            el.Text({ color: statusColor, children: [status] }),
          ],
        }),
      ],
    }))
    if (!isOpen) return
    if (thread) body.push(threadBox(el, s.id, thread, on))
    if (sec.status === 'loading') {
      body.push(el.Box({ paddingLeft: 2, paddingY: 1, children: [el.Text({ color: C.dim, children: ['현재 대화를 바탕으로 만드는 중…'] })] }))
      return
    }
    if (sec.status === 'error') {
      body.push(el.Box({ paddingLeft: 2, paddingY: 1, children: [el.Text({ color: C.red, children: ['만들지 못했습니다: ' + sec.error + '. r을 누르면 다시 만듭니다.'] })] }))
      return
    }
    if (sec.status !== 'done') return
    const inner = cols - 2
    const d = sec.data
    let view
    if (s.id === 'summary') view = summaryView(el, d, changed, on.openDiff)
    else if (s.id === 'background') view = backgroundView(el, d)
    else if (s.id === 'walk') view = walkView(el, d, st.codeFor, inner, st.pans)
    else if (s.id === 'flow') view = flowView(el, d, inner)
    else if (s.id === 'ba') view = baView(el, d)
    else if (s.id === 'impact') view = impactView(el, d)
    else if (s.id === 'terms') view = termsView(el, d, st.known, on.toggleKnown)
    else if (s.id === 'quiz') view = quizView(el, d, st.quiz, on)
    else {
      const maxLeft = seqMaxLeft(d, inner)
      // 위치는 창(pan.js)이 끌기와 키로도 바꾼다. 버튼의 흐림만 여기서 판단
      const left = st.seqLeft
      const diagram = seqView(el, d, inner, left)
      view = maxLeft === 0 ? diagram : el.Box({
        flexDirection: 'column',
        rowGap: 1,
        children: [
          buttonRow(el, [
            btn(el, { key: 'seq-left', hotkey: 'h', label: '왼쪽', dim: left === 0, onPress: () => on.seqShift(-STEP_COLS, maxLeft) }),
            btn(el, { key: 'seq-right', hotkey: 'l', label: '오른쪽', dim: left >= maxLeft, onPress: () => on.seqShift(STEP_COLS, maxLeft) }),
            el.Text({ color: C.faint, children: [' 창보다 넓은 다이어그램' + (left ? '  ·  가로 +' + left : '')] }),
          ]),
          diagram,
        ],
      })
    }
    body.push(el.Box({ paddingLeft: 2, paddingY: 1, children: [view] }))
  })
  body.push(rule(el, cols))

  const ask = el.Box({
    flexDirection: 'column',
    rowGap: 1,
    children: [
      el.Text({ bold: true, color: C.accent, children: ['질문하기'] }),
      ...st.qa.map((x, i) => el.Box({
        key: 'qa-' + i,
        flexDirection: 'column',
        paddingLeft: 2,
        children: [
          rich(el, [['Q  ', C.accent, true], [x.q, C.title]]),
          x.a === null ? el.Text({ color: C.dim, children: ['   답을 만드는 중…'] }) : rich(el, [['A  ', C.green, true], [x.a, C.fg]]),
        ],
      })),
      el.Input({ key: 'ask', label: '질문', placeholder: '이 변경에 대해 궁금한 점을 입력하고 Enter', value: '', submitLabel: '묻기', onSubmit: (v) => { if (v.trim()) on.ask(v.trim()) } }),
      el.Text({ color: C.faint, children: ['본 대화에는 남지 않습니다.'] }),
    ],
  })

  return el.Box({
    flexDirection: 'column',
    children: [
      header,
      el.Text({ children: [' '] }),
      ...body,
      ask,
      rule(el, cols),
      el.Text({ color: C.faint, children: ['휠·↑↓·PgUp/PgDn 위아래  목차로 섹션 이동  1–9 펼치기·접기  Esc 닫기'] }),
      el.Text({ color: C.faint, children: ['대화 기록을 바탕으로 재구성한 해설입니다. 실제 내부 추론과 다를 수 있습니다.'] }),
    ],
  })
}

files.hooks/views/list.js:
// 작업 목록 창: 이 세션의 턴과 지난 작업. 한 줄 = 바뀐 턴 하나 (세션으로 묶지 않는다).
//
// st = {
//   status, progress, error,
//   turns: [{ seq, turnId, title, files, added, removed, understood }],     이 세션 (실시간 기록)
//   past: [{ sessionId, id, seq, request, at, subjects, fileNames, files, commits, understood }]
//                                                                            지난 세션들의 바뀐 턴 (최근 것부터, 불러오며 채워진다)
//   usage: { calls, input, output, cacheRead, cacheWrite }                   이 저장소에서 해설에 쓴 토큰
// }

import { C, btn, buttonRow, link, rich, rule } from './common.js'

// 1234 → 1.2k
export const k = (n) => (n >= 10000 ? Math.round(n / 1000) + 'k' : n >= 1000 ? (n / 1000).toFixed(1) + 'k' : String(n))

export function usageText(u) {
  if (!u || !u.calls) return '아직 없음'
  return '호출 ' + u.calls + '회 · 입력 ' + k(u.input + u.cacheRead + u.cacheWrite) + ' (캐시 읽기 ' + k(u.cacheRead) + ') · 출력 ' + k(u.output)
}

const mark = (understood) => (understood ? ['✓ 이해함', C.green, true] : ['○ 아직', C.faint])
const sep = ['  ·  ', C.faint]

// 지난 턴의 제목: 커밋 메시지, 없으면 바꾼 파일 이름 ("가자" 같은 요청만으로는 무슨 일인지 모른다)
function pastTitle(t) {
  if (t.subjects.length) return t.subjects[0] + (t.subjects.length > 1 ? '  외 커밋 ' + (t.subjects.length - 1) + '개' : '')
  return t.fileNames.slice(0, 3).join(', ') + (t.fileNames.length > 3 ? ' 외 ' + (t.fileNames.length - 3) + '개' : '')
}

export function listView(el, cols, st, on) {
  const out = [
    rich(el, [['작업 목록  ', C.accent, true], ['고르면 해설 창이 열립니다. 아직 이해하지 않은 턴은 ○', C.dim]]),
    rich(el, [['해설에 쓴 토큰 (이 저장소 누적)  ', C.faint], [usageText(st.usage), C.dim]], { wrap: 'truncate-end' }),
    el.Box({ marginTop: 1, children: [buttonRow(el, [
      btn(el, { key: 'refresh', hotkey: 'r', label: '다시 찾기', dim: st.status === 'loading', onPress: on.refresh }),
      ...(on.back ? [btn(el, { key: 'back', hotkey: 'b', label: '해설로', onPress: on.back })] : []),
    ])] }),
  ]

  // 지난 턴을 여는 중이거나 실패했으면 목록 위에 (긴 목록 아래에 두면 보이지 않는다)
  if (st.opening) out.push(el.Text({ color: C.accent, children: [st.progress] }))
  if (st.error) out.push(el.Text({ color: C.red, children: [st.error] }))
  out.push(rule(el, cols), el.Text({ bold: true, color: C.title, children: ['이 세션'] }))
  if (!st.turns.length) out.push(el.Text({ color: C.faint, children: ['  아직 기록된 변경이 없습니다.'] }))
  for (const t of [...st.turns].reverse()) {
    out.push(el.Box({
      flexDirection: 'column',
      children: [
        link(el, { key: 'turn-' + t.turnId, label: '#' + t.seq + '  ' + t.title, onPress: () => on.openTurn(t) }),
        rich(el, ['  ', ['파일 ' + t.files + '  ', C.dim], ['+' + t.added, C.green], ' ', ['−' + t.removed, C.red], sep, mark(t.understood)], { wrap: 'truncate-end' }),
      ],
    }))
  }

  out.push(rule(el, cols), rich(el, [['지난 작업', C.title, true], st.status === 'loading' ? ['  ' + (st.progress || '찾는 중…'), C.dim] : '']))
  if (!st.past.length && st.status !== 'loading') out.push(el.Text({ color: C.faint, children: ['  이 프로젝트의 지난 대화에서 바뀐 것이 없습니다.'] }))
  for (const t of st.past) {
    out.push(el.Box({
      flexDirection: 'column',
      children: [
        link(el, { key: 'past-' + t.id, label: pastTitle(t), onPress: () => on.openPast(t) }),
        rich(el, ['  ', [t.at, C.dim], sep, [t.request, C.dim], sep, mark(t.understood)], { wrap: 'truncate-end' }),
      ],
    }))
  }

  return el.Box({ flexDirection: 'column', children: out })
}

