// 턴 기록을 다루는 순수 함수. 파일 읽기·쓰기는 register.js가 한다.

import { lineStats } from './diff.js'

// 파일 하나를 통째로 다룰 수 있는 최대 크기 ($.fs 제한과 같다)
export const MAX_FILE_BYTES = 4 * 1024 * 1024

// 이 mod가 기록하는 수정 도구
export const EDIT_TOOLS = ['Edit', 'Write', 'MultiEdit', 'NotebookEdit']

// 도구 입력에서 고친 파일 경로를 꺼낸다
export function editedPath(e) {
  return e.file_path || e.notebook_path || null
}

// 상대 경로면 작업 디렉터리 기준 절대 경로로
export function absolutePath(path, cwd) {
  if (path.startsWith('/')) return normalize(path)
  return normalize(cwd.replace(/\/$/, '') + '/' + path)
}

function normalize(path) {
  const out = []
  for (const part of path.split('/')) {
    if (part === '' || part === '.') continue
    if (part === '..') out.pop()
    else out.push(part)
  }
  return '/' + out.join('/')
}

// 저장소 안이면 저장소 기준 상대 경로, 밖이면 절대 경로를 '_outside/' 아래로
export function storedPath(abs, root) {
  const base = root.replace(/\/$/, '') + '/'
  if (abs.startsWith(base)) return abs.slice(base.length)
  return '_outside' + abs
}

// 글이 텍스트로 다룰 수 없는 내용인지 (NUL 문자가 있으면 바이너리로 본다)
export function looksBinary(text) {
  return text.includes('\u0000')
}

// 요청문 첫 줄로 턴 제목을 만든다 (모델을 부르지 않는다)
export function turnTitle(request, max = 60) {
  const first = (request || '').split('\n').map((x) => x.trim()).find((x) => x) || '(요청 없음)'
  return first.length > max ? first.slice(0, max - 1) + '…' : first
}

// repos: Bash가 건드린 git 저장소의 턴 시작 상태 (register.js의 snapshotRepo)
export function newTurn(turnId, request, startedAt) {
  return { turnId, request: request || '', startedAt, files: {}, repos: {} }
}

// 턴에서 처음 건드리는 파일의 기록. before가 null이면 새 파일, skipped면 내용을 다루지 않는다
export function newFileEntry(abs, rel, before, skipped) {
  return { abs, rel, before, isNew: before === null && !skipped, skipped: skipped || null, edits: 0, tools: [], agents: [] }
}

// 성공한 수정 한 번을 기록한다
export function recordEdit(entry, tool, agent) {
  const tools = entry.tools.includes(tool) ? entry.tools : [...entry.tools, tool]
  const agents = agent && !entry.agents.some((x) => x.agentId === agent.agentId) ? [...entry.agents, agent] : entry.agents
  return { ...entry, edits: entry.edits + 1, tools, agents }
}

// 저장할 턴 기록 (스냅숏 내용은 빼고 파일 목록과 줄 수만)
export function turnRecord(turn, afters, extra) {
  const files = Object.values(turn.files)
    .filter((f) => f.edits > 0)
    .map((f) => {
      const after = afters[f.abs]
      const changed = f.skipped ? true : f.before !== after
      const stats = f.skipped ? { added: 0, removed: 0 } : lineStats(f.before, after ?? '')
      return {
        path: f.rel,
        absPath: f.abs,
        isNew: f.isNew,
        skipped: f.skipped,
        tools: f.tools,
        agents: f.agents,
        changed,
        added: stats.added,
        removed: stats.removed,
      }
    })
  const changedFiles = files.filter((f) => f.changed)
  return {
    turnId: turn.turnId,
    title: turnTitle(turn.request),
    request: turn.request,
    startedAt: turn.startedAt,
    files,
    added: changedFiles.reduce((a, f) => a + f.added, 0),
    removed: changedFiles.reduce((a, f) => a + f.removed, 0),
    hasChanges: changedFiles.length > 0,
    ...extra,
  }
}

// 세션 목록에 올릴 턴 요약
export function turnSummary(record) {
  return {
    seq: record.seq,
    turnId: record.turnId,
    title: record.title,
    endedAt: record.endedAt,
    files: record.files.filter((f) => f.changed).length,
    added: record.added,
    removed: record.removed,
    agents: [...new Set(record.files.flatMap((f) => f.agents.map((a) => a.type || 'subagent')))],
    understood: false,
  }
}

// 저장 위치의 저장소 폴더 이름: 저장소 이름 + 경로 해시 8자리
export async function repoFolder(root) {
  const name = root.replace(/\/$/, '').split('/').pop() || 'root'
  const bytes = new TextEncoder().encode(root)
  const hash = await crypto.subtle.digest('SHA-1', bytes)
  const hex = [...new Uint8Array(hash)].map((x) => x.toString(16).padStart(2, '0')).join('')
  return name.replace(/[^A-Za-z0-9._-]/g, '_') + '-' + hex.slice(0, 8)
}

files.hooks/views/pan.js:
// 가로로 넓은 내용(시퀀스 다이어그램, diff 코드, 코드 줄)을 담는 창 (Client 모듈).
// 휠과 트랙패드의 가로 움직임은 mod에 전달되지 않는다. 그래서 마우스로 끌거나 ←/→(h/l) 키로 가로 이동한다.
// 클릭하면 이 창이 키를 받으므로, 쓰지 않는 키는 훅 모듈로 넘긴다(post). Esc로 창 단축키로 돌아간다.
//
// props = {
//   id: 'seq' | 'diff' | 'walk-3' …   훅 모듈이 위치를 기억하는 이름
//   left: 가로 위치 (창의 h/l 버튼이 바꾸면 따라간다)
//   rows: [{ segs: [{ fixed: parts, parts, bg }], sep }   segs가 둘이면 반씩 나누고 sep 색의 │로 가른다
//          | { center: [text, color] }]                   가운데 정렬, 밀지 않는다 (접힌 줄 표시 등)
//   hint: 넓을 때 아래에 보일 안내 색
// }
// part = [text, color, bold?, background?]. fixed는 밀지 않는 앞부분(줄 번호 등), parts만 민다.

const STEP = 8

// 한글 등 넓은 글자는 2칸
function wide(c) {
  return (c >= 0x1100 && c <= 0x115f) || (c >= 0x2e80 && c <= 0xa4cf) || (c >= 0xac00 && c <= 0xd7a3) ||
    (c >= 0xf900 && c <= 0xfaff) || (c >= 0xfe30 && c <= 0xfe4f) || (c >= 0xff00 && c <= 0xff60) || (c >= 0xffe0 && c <= 0xffe6)
}

function cells(s) {
  let n = 0
  for (const ch of s) n += wide(ch.codePointAt(0)) ? 2 : 1
  return n
}

const textOf = (parts) => (parts || []).map((p) => p[0]).join('')

// 색 조각들의 앞에서 n글자를 버린다
function shift(parts, n) {
  const out = []
  let rest = n
  for (const p of parts || []) {
    const t = p[0]
    if (rest >= t.length) { rest -= t.length; continue }
    out.push(rest ? [t.slice(rest), p[1], p[2], p[3]] : p)
    rest = 0
  }
  return out
}

// 가장 많이 밀 수 있는 만큼: 가장 긴 줄이 창 끝에 닿을 때까지
function maxLeftOf(rows, columns) {
  let max = 0
  for (const row of rows || []) {
    if (!row.segs) continue
    const width = row.segs.length > 1 ? Math.floor((columns - 1) / row.segs.length) : columns
    for (const seg of row.segs) max = Math.max(max, cells(textOf(seg.parts)) - (width - cells(textOf(seg.fixed))))
  }
  return Math.max(0, max)
}

export default function Pan(props, surface) {
  const { Box, Text } = surface.elements
  const p = props || {}
  let st = surface.state
  if (!st) {
    st = { left: p.left || 0, seen: p.left || 0, max: 0, drag: null }
    const move = (left) => {
      const s = surface.state
      const next = Math.max(0, Math.min(s.max, left))
      if (next === s.left) return
      surface.setState({ ...s, left: next })
      surface.post({ pan: s.id, left: next })
    }
    // 끌기: 누른 곳에서 오른쪽으로 끌면 내용이 따라 오른쪽으로 (왼쪽 내용이 보인다)
    surface.onPointer((e) => {
      const s = surface.state
      if (!s) return
      if (e.type === 'down' && e.button === 'left') surface.setState({ ...s, drag: { x: e.x, left: s.left } })
      else if (e.type === 'move' && s.drag && e.button) move(s.drag.left - (e.x - s.drag.x))
      else if (e.type === 'up' && s.drag) surface.setState({ ...surface.state, drag: null })
    })
    surface.onKey((e) => {
      const s = surface.state
      if (!s) return
      if (e.key === 'right' || e.key === 'l') move(s.left + STEP)
      else if (e.key === 'left' || e.key === 'h') move(s.left - STEP)
      else if (e.key === 'home') move(0)
      else if (e.key === 'end') move(s.max)
      else surface.post({ pan: s.id, key: e.key })
    })
    surface.setState(st)
  }
  // 창의 h/l 버튼으로 위치가 바뀌었으면 따라간다
  st.id = p.id
  if ((p.left || 0) !== st.seen) {
    st.seen = p.left || 0
    st.left = st.seen
  }
  const columns = surface.columns || 80
  st.max = maxLeftOf(p.rows, columns)
  const left = Math.min(st.left, st.max)

  const line = (parts) => Text({
    wrap: 'truncate-end',
    children: parts.map((q) => {
      const t = { color: q[1], bold: !!q[2], children: [q[0]] }
      if (q[3]) t.backgroundColor = q[3]
      return Text(t)
    }),
  })
  const out = (p.rows || []).map((row) => {
    if (row.center) return Box({ justifyContent: 'center', children: [Text({ color: row.center[1], children: [row.center[0]] })] })
    const width = row.segs.length > 1 ? Math.floor((columns - 1) / row.segs.length) : columns
    const boxes = []
    row.segs.forEach((seg, i) => {
      if (i) boxes.push(Text({ color: row.sep, children: ['│'] }))
      const b = { width, flexShrink: 0, children: [line([...(seg.fixed || []), ...shift(seg.parts, left)])] }
      if (seg.bg) b.backgroundColor = seg.bg
      boxes.push(Box(b))
    })
    return Box({ flexDirection: 'row', children: boxes })
  })
  if (st.max > 0 && p.hint) {
    out.push(Text({ color: p.hint, wrap: 'truncate-end', children: ['끌거나 클릭 후 ←/→ 로 가로 이동' + (left ? '  ·  가로 +' + left : '') + '  ·  Esc: 창 단축키로'] }))
  }
  return Box({ flexDirection: 'column', children: out })
}

files.hooks/views/diagrams.js:
// 흐름도(테두리 카드)와 시퀀스(레인 다이어그램). 모델이 준 구조를 mod가 칸을 계산해 그린다.

import { C, rich, shift } from './common.js'

// 색은 그릴 때 읽는다 (테마 설정이 C를 바꾸므로)
const kindColor = (kind) => ({ step: C.faint, cond: C.blue, changed: C.accent, ok: C.green, err: C.red })[kind] || C.faint

// ── 흐름도 ───────────────────────────────────────────────────
// data: { nodes: [{ title, desc, kind, tag, next, branch }] }

function card(el, item, n, width) {
  const color = kindColor(item.kind)
  const titleColor = item.kind === 'err' ? C.red : item.kind === 'ok' ? C.green : C.title
  const rows = [rich(el, [n ? [n + '  ', C.accent, true] : '', [item.title, titleColor, true]])]
  if (item.desc) rows.push(el.Text({ color: C.dim, children: [item.desc] }))
  if (item.tag) rows.push(el.Text({ color: C.accent, children: [item.tag] }))
  const props = { flexDirection: 'column', borderStyle: 'round', borderColor: color, paddingX: 1, children: rows }
  if (width) props.width = width
  return el.Box(props)
}

export function flowView(el, data, cols) {
  const cardW = Math.min(34, cols - 2)
  // 옆 가지 카드를 나란히 둘 공간이 없으면 카드 아래로 내린다
  const wide = cols >= cardW + 34
  const out = [
    rich(el, [
      ['■ ', C.accent], ['이번에 추가  ', C.dim],
      ['■ ', C.blue], ['조건  ', C.dim],
      ['■ ', C.green], ['정상 종료  ', C.dim],
      ['■ ', C.red], ['에러', C.dim],
    ]),
    el.Text({ children: [' '] }),
  ]
  data.nodes.forEach((item, i) => {
    const main = card(el, item, i + 1, cardW)
    if (item.branch) {
      const arrow = el.Text({ color: kindColor(item.branch.kind), children: [' ─ ' + (item.branch.label || '') + ' ─> '] })
      const side = card(el, item.branch, 0)
      out.push(
        wide
          ? el.Box({ flexDirection: 'row', alignItems: 'center', children: [main, arrow, side] })
          : el.Box({
              flexDirection: 'column',
              children: [main, el.Box({ flexDirection: 'row', alignItems: 'center', paddingLeft: 3, children: [el.Text({ color: C.faint, children: ['└'] }), arrow, side] })],
            }),
      )
    } else {
      out.push(main)
    }
    if (i < data.nodes.length - 1) {
      out.push(el.Box({ paddingLeft: Math.floor(cardW / 2), children: [rich(el, [['│', C.faint], item.next ? ['  ' + item.next, C.dim] : ''])] }))
    }
  })
  return el.Box({ flexDirection: 'column', children: out })
}

// ── 시퀀스 ───────────────────────────────────────────────────
// data: { lanes: [{ name }], msgs: [{ from, to, label, kind, note }] }
// 호출마다 위 줄에 번호와 라벨, 아래 줄에 화살표, 그 아래 흐린 설명.
// 라벨과 설명은 줄 끝에만 둔다(한글 폭 때문에). 왼쪽 번호 칸은 고정, 나머지는 left만큼 가로로 민다.

const GUTTER = 3
const laneColor = (i) => [C.dim, C.fg, C.accent, C.blue, C.purple, C.green][i % 6]
const msgColor = (kind) => ({ normal: C.fg, changed: C.accent, fail: C.red, ok: C.green })[kind] || C.fg

function widthOf(s) {
  let w = 0
  for (const ch of s) {
    const c = ch.codePointAt(0)
    w += (c >= 0x1100 && c <= 0x115f) || (c >= 0x2e80 && c <= 0xa4cf) || (c >= 0xac00 && c <= 0xd7a3) ||
      (c >= 0xf900 && c <= 0xfaff) || (c >= 0xff00 && c <= 0xff60) ? 2 : 1
  }
  return w
}

function geometry(data, cols) {
  const laneW = Math.max(12, Math.min(20, Math.floor((cols - GUTTER) / data.lanes.length)))
  const center = (i) => i * laneW + Math.floor(laneW / 2)
  const width = laneW * data.lanes.length
  let longest = width
  data.msgs.forEach((m) => {
    const start = Math.min(center(m.from), center(m.to)) + 2
    longest = Math.max(longest, start + widthOf(m.label), start + widthOf(m.note || ''))
  })
  return { laneW, center, width, longest }
}

export function seqMaxLeft(data, cols) {
  return Math.max(0, geometry(data, cols).longest - (cols - GUTTER))
}

// 창보다 넓으면 끌거나 ←/→ 로 가로 이동하는 창(pan.js)에 담는다
export function seqView(el, data, cols, left) {
  const { laneW, center, width } = geometry(data, cols)
  const lifeline = () => {
    const a = new Array(width).fill(' ')
    data.lanes.forEach((_, i) => { a[center(i)] = '│' })
    return a
  }
  const row = (gutter, parts) => ({ segs: [{ fixed: [[gutter, C.accent, true]], parts }] })
  const paint = (cells, start, end, color) => [
    [cells.slice(0, start).join(''), C.faint],
    [cells.slice(start, end).join(''), color],
    [cells.slice(end).join(''), C.faint],
  ]
  const textAt = (col, parts) => [[lifeline().slice(0, col).join(''), C.faint], ...parts]

  // 참여자 머리 상자 세 줄. 아래 테두리의 ┬가 생명선과 같은 칸에 온다
  const inner = laneW - 3
  const colorOf = laneColor
  const fit = (name) => (name.length > inner ? name.slice(0, inner - 1) + '…' : name)
  const middle = (name) => {
    const t = fit(name)
    const padTotal = inner - t.length
    return ' '.repeat(Math.floor(padTotal / 2)) + t + ' '.repeat(padTotal - Math.floor(padTotal / 2))
  }
  const boxLine = (fn) => data.lanes.map((l, i) => [fn(l).padEnd(laneW, ' '), colorOf(i), true])
  const rows = [
    row('   ', boxLine(() => '╭' + '─'.repeat(inner) + '╮')),
    row('   ', boxLine((l) => '│' + middle(l.name) + '│')),
    row('   ', boxLine(() => '╰' + '─'.repeat(Math.floor(laneW / 2) - 1) + '┬' + '─'.repeat(inner - Math.floor(laneW / 2)) + '╯')),
  ]
  data.msgs.forEach((m, i) => {
    const color = msgColor(m.kind)
    const l = Math.min(center(m.from), center(m.to))
    const r = Math.max(center(m.from), center(m.to))
    rows.push(row(String(i + 1).padStart(2, ' ') + ' ', textAt(l + 2, [[m.label, color, true]])))
    const a = lifeline()
    if (m.from === m.to) {
      const c = center(m.from)
      const b = lifeline()
      a[c] = '├'; a[c + 1] = '─'; a[c + 2] = '╮'
      b[c] = '│'; b[c + 1] = '<'; b[c + 2] = '╯'
      rows.push(row('   ', paint(a, c, c + 3, color)))
      rows.push(row('   ', paint(b, c + 1, c + 3, color)))
    } else {
      for (let k = l + 1; k < r; k++) a[k] = '─'
      if (m.from < m.to) a[r - 1] = '>'
      else a[l + 1] = '<'
      rows.push(row('   ', paint(a, l + 1, r, color)))
    }
    if (m.note) rows.push(row('   ', textAt(l + 2, [[m.note, C.dim]])))
  })
  rows.push(row('   ', [[lifeline().join(''), C.faint]]))
  return el.Client({ key: 'pan-seq', module: './pan.js', width: cols, props: { id: 'seq', left, rows, hint: C.faint } })
}

